    module = load_inline(
        name="tanh_ext",
        cpp_sources="""
            #include <torch/extension.h>
            void launch_tanh_kernel(const at::Tensor& input, at::Tensor& output);
        """,
        cuda_sources=cuda_source,
        functions=["launch_tanh_kernel"],
        verbose=True
    )

